 * Minimal hash-based SPA router (jsdom-compatible, no History API).
 */

/** Split a hash path into pathname and query object. */
function parsePath(raw) {
  let path = raw;
  let search = '';
  const qIndex = raw.indexOf('?');
  if (qIndex !== -1) {
    path = raw.slice(0, qIndex);
    search = raw.slice(qIndex + 1);
  }
  const query = {};
  if (search) {
    for (const pair of search.split('&')) {
      if (!pair) continue;
      const eq = pair.indexOf('=');
      const key = eq === -1 ? pair : pair.slice(0, eq);
      const value = eq === -1 ? '' : pair.slice(eq + 1);
      query[decodeURIComponent(key)] = decodeURIComponent(value);
    }
  }
  return { path, query };
}

/** Match a concrete path against a pattern like /users/:id. Returns params or null. */
function matchPattern(pattern, path) {
  const patternParts = pattern.split('/').filter(Boolean);
  const pathParts = path.split('/').filter(Boolean);
  if (patternParts.length !== pathParts.length) return null;

  const params = {};
  for (let i = 0; i < patternParts.length; i++) {
    const pp = patternParts[i];
    if (pp.startsWith(':')) {
      params[pp.slice(1)] = decodeURIComponent(pathParts[i]);
    } else if (pp !== pathParts[i]) {
      return null;
    }
  }
  return params;
}

export function createRouter(routes, { onChange } = {}) {
  const normalizedRoutes = Object.entries(routes).map(([pattern, handler]) => ({
    pattern: pattern.replace(/^#/, ''),
    handler,
  }));

  let destroyed = false;

  function resolve() {
    // location.hash includes the leading '#'; strip it.
    const raw = window.location.hash.startsWith('#')
      ? window.location.hash.slice(1)
      : window.location.hash;
    const { path, query } = parsePath(raw);

    for (const route of normalizedRoutes) {
      const params = matchPattern(route.pattern, path);
      if (params) {
        route.handler({ params, query });
        if (onChange) onChange({ path, params, query });
        return;
      }
    }

    if (routes.notFound) {
      routes.notFound({ path, params: {}, query });
      if (onChange) onChange({ path, params: {}, query });
    }
  }

  function navigate(path) {
    window.location.hash = path.startsWith('#') ? path : `#${path}`;
  }

  function onClick(event) {
    if (event.defaultPrevented) return;
    if (event.button !== 0) return; // left click only
    if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;

    const target = event.target && event.target.closest
      ? event.target.closest('a[href]')
      : null;
    if (!target) return;

    const href = target.getAttribute('href');
    if (!href || !href.startsWith('#/')) return;

    event.preventDefault();
    navigate(href.slice(1));
  }

  function start() {
    window.addEventListener('hashchange', resolve);
    document.addEventListener('click', onClick);
    resolve(); // route the current hash immediately
  }

  function destroy() {
    if (destroyed) return;
    destroyed = true;
    window.removeEventListener('hashchange', resolve);
    document.removeEventListener('click', onClick);
  }

  return { start, destroy, navigate, resolve };
}
