result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hash-router/tests/router.test.js", "content": "import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createRouter } from '../src/router.js';

function setHash(hash) {
  window.location.hash = hash;
  window.dispatchEvent(new window.HashChangeEvent('hashchange'));
}

function clickAnchor(anchor, { ctrlKey = false, metaKey = false } = {}) {
  const event = new MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    button: 0,
    ctrlKey,
    metaKey,
  });
  anchor.dispatchEvent(event);
  return event.defaultPrevented;
}

describe('createRouter', () => {
  let router;

  beforeEach(() => {
    document.body.innerHTML = '';
    window.location.hash = '';
  });

  afterEach(() => {
    if (router) {
      router.destroy();
      router = undefined;
    }
  });

  it('routes the current hash on start', () => {
    window.location.hash = '#/users/42';
    const handler = vi.fn();
    router = createRouter({ '#/users/:id': handler });
    router.start();
    expect(handler).toHaveBeenCalledTimes(1);
    expect(handler).toHaveBeenCalledWith({ params: { id: '42' }, query: {} });
  });

  it('responds to hashchange events with params and query', () => {
    const users = vi.fn();
    const home = vi.fn();
    router = createRouter({
      '#/users/:id': users,
      '#/': home,
    });
    router.start();

    setHash('#/');
    expect(home).toHaveBeenCalledWith({ params: {}, query: {} });

    setHash('#/users/7');
    expect(users).toHaveBeenCalledWith({ params: { id: '7' }, query: {} });

    setHash('#/users/9?tab=posts&sort=asc');
    expect(users).toHaveBeenLastCalledWith({
      params: { id: '9' },
      query: { tab: 'posts', sort: 'asc' },
    });
    expect(home).toHaveBeenCalledTimes(1);
  });

  it('parses query strings including encoded values', () => {
    const handler = vi.fn();
    router = createRouter({ '#/search': handler });
    router.start();

    setHash('#/search?q=hello%20world&flag&empty=');
    expect(handler).toHaveBeenLastCalledWith({
      params: {},
      query: { q: 'hello world', flag: '', empty: '' },
    });
  });

  it('supports multiple params in a pattern', () => {
    const handler = vi.fn();
    router = createRouter({ '#/users/:userId/posts/:postId': handler });
    router.start();

    setHash('#/users/3/posts/99');
    expect(handler).toHaveBeenCalledWith({
      params: { userId: '3', postId: '99' },
      query: {},
    });
  });

  it('falls back to notFound for unmatched paths', () => {
    const notFound = vi.fn();
    const handler = vi.fn();
    router = createRouter(
      { '#/known': handler, notFound },
    );
    router.start();

    setHash('#/nope');
    expect(notFound).toHaveBeenCalledWith({ path: '/nope', params: {}, query: {} });
    expect(handler).not.toHaveBeenCalled();
  });

  it('navigate() sets the hash and triggers routing (round-trip)', () => {
    const handler = vi.fn();
    router = createRouter({ '#/about': handler });
    router.start();

    router.navigate('/about');
    expect(window.location.hash).toBe('#/about');
    // hashchange fires synchronously in jsdom
    expect(handler).toHaveBeenCalledTimes(1);

    router.navigate('/about');
    // Setting the same hash does not fire another hashchange
    expect(handler).toHaveBeenCalledTimes(1);

    router.navigate('/about?x=1');
    expect(handler).toHaveBeenCalledTimes(2);
    expect(handler).toHaveBeenLastCalledWith({ params: {}, query: { x: '1' } });
  });

  it('intercepts plain clicks on #/-anchors and routes them', () => {
    const handler = vi.fn();
    router = createRouter({ '#/users/5': handler });
    router.start();

    document.body.innerHTML = '<a href="#/users/5" id="link">go</a>';
    const anchor = document.getElementById('link');

    const prevented = clickAnchor(anchor);
    expect(prevented).toBe(true); // default navigation suppressed
    expect(window.location.hash).toBe('#/users/5');
    expect(handler).toHaveBeenCalledTimes(1);
    expect(handler).toHaveBeenCalledWith({ params: { id: '5' }, query: {} });
  });

  it('preserves default behavior for modified clicks (ctrl/meta)', () => {
    const handler = vi.fn();
    router = createRouter({ '#/users/6': handler });
    router.start();

    document.body.innerHTML = '<a href="#/users/6" id="link">go</a>';
    const anchor = document.getElementById('link');

    expect(clickAnchor(anchor, { ctrlKey: true })).toBe(false);
    expect(clickAnchor(anchor, { metaKey: true })).toBe(false);
    expect(window.location.hash).not.toBe('#/users/6');
    expect(handler).not.toHaveBeenCalled();
  });

  it('ignores anchors whose href is not hash-slash', () => {
    const handler = vi.fn();
    router = createRouter({ '#/x': handler });
    router.start();

    document.body.innerHTML =
      '<a href="https://example.com" id="ext"></a>' +
      '<a href="#plain" id="plain"></a>';
    const ext = document.getElementById('ext');
    const plain = document.getElementById('plain');

    expect(clickAnchor(ext)).toBe(false);
    expect(clickAnchor(plain)).toBe(false);
    expect(handler).not.toHaveBeenCalled();
  });

  it('destroy() removes all listeners', () => {
    const handler = vi.fn();
    router = createRouter({ '#/a': handler });
    router.start();
    router.destroy();
    router = undefined;

    setHash('#/a');
    expect(handler).not.toHaveBeenCalled();
  });
});
"})
